/**
 * @file index.d.ts
 * @description Comprehensive TypeScript declarations for scirs2-wasm.
 *
 * This file provides hand-authored type declarations that supplement the
 * auto-generated wasm-bindgen `*.d.ts` file.  Import from `scirs2-wasm`
 * (the package entry-point) rather than from this file directly.
 *
 * All numeric arrays accepted by the WASM layer may be passed as either
 * a native `Float64Array` or a plain `number[]`; the JS/WASM bridge
 * converts both transparently.
 */

// ---------------------------------------------------------------------------
// Re-export raw WASM types (generated by wasm-bindgen)
// ---------------------------------------------------------------------------
export type { WasmArray, WasmMatrix, PerformanceTimer } from "../pkg/scirs2_wasm";

// ===========================================================================
// SECTION 1 — Statistics: descriptive structs
// ===========================================================================

/**
 * Full descriptive statistics for a numeric dataset.
 *
 * Obtained from {@link compute_descriptive_stats}.
 *
 * All statistics use **population** formulas (ddof=0) for variance and
 * standard deviation.  The `count` field is the number of non-NaN
 * observations.
 *
 * Call `.free()` when done to release WASM memory.
 */
export interface IDescriptiveStats {
    /** Arithmetic mean. */
    readonly mean: number;
    /** Population variance (ddof=0). */
    readonly variance: number;
    /** Population standard deviation (ddof=0). */
    readonly std_dev: number;
    /** Minimum value in the dataset. */
    readonly min: number;
    /** Maximum value in the dataset. */
    readonly max: number;
    /** Median (50th percentile via linear interpolation). */
    readonly median: number;
    /** Fisher's skewness (third standardised central moment). */
    readonly skewness: number;
    /**
     * Excess kurtosis (fourth standardised central moment minus 3).
     * Positive values indicate heavier tails than a normal distribution.
     */
    readonly kurtosis: number;
    /** Number of observations. */
    readonly count: number;
    /** Sum of all observations. */
    readonly sum: number;
    /** First quartile (25th percentile). */
    readonly q25: number;
    /** Third quartile (75th percentile). */
    readonly q75: number;
    /** Interquartile range (q75 - q25). */
    readonly iqr: number;
}

/**
 * WASM-backed class; implements {@link IDescriptiveStats}.
 * Must call `.free()` after use.
 */
export declare class DescriptiveStats implements IDescriptiveStats {
    readonly mean: number;
    readonly variance: number;
    readonly std_dev: number;
    readonly min: number;
    readonly max: number;
    readonly median: number;
    readonly skewness: number;
    readonly kurtosis: number;
    readonly count: number;
    readonly sum: number;
    readonly q25: number;
    readonly q75: number;
    readonly iqr: number;
    free(): void;
}

/**
 * Compute comprehensive descriptive statistics for a dataset.
 *
 * Returns a {@link DescriptiveStats} object — **must be freed** after use.
 *
 * @example
 * ```ts
 * const ds = compute_descriptive_stats(new Float64Array([1, 2, 3, 4, 5]));
 * console.log(ds.mean, ds.std_dev, ds.skewness);
 * ds.free();
 * ```
 */
export declare function compute_descriptive_stats(
    data: Float64Array | number[]
): DescriptiveStats;

