// SECTION 2 — Statistics: linear regression
// ===========================================================================

/**
 * OLS simple linear regression result: y = slope·x + intercept.
 *
 * Obtained from {@link wasm_linear_regression_typed}.
 * Must call `.free()` after use.
 */
export declare class WasmLinearModel {
    /** Regression slope β₁. */
    readonly slope: number;
    /** Regression intercept β₀. */
    readonly intercept: number;
    /** Coefficient of determination R² ∈ [0, 1]. */
    readonly r_squared: number;
    /** Standard error of the slope estimate. */
    readonly std_err_slope: number;
    /** Standard error of the intercept estimate. */
    readonly std_err_intercept: number;
    /** Number of observations used. */
    readonly n: number;

    /**
     * Predict ŷ for a new x value.
     * @param x — predictor value.
     */
    predict(x: number): number;

    /**
     * Predict ŷ for an array of x values.
     * @param xs — predictor values.
     */
    predict_batch(xs: Float64Array | number[]): Float64Array;

    free(): void;
}

/**
 * Fit OLS simple linear regression y = slope·x + intercept.
 *
 * Returns a {@link WasmLinearModel} — **must be freed** after use.
 * All fields are `NaN` if the input is invalid (fewer than 2 points,
 * length mismatch, or constant x).
 */
export declare function wasm_linear_regression_typed(
    x: Float64Array | number[],
    y: Float64Array | number[]
): WasmLinearModel;

