/**
 * Result of a Student's t-test.
 *
 * Obtained from {@link wasm_t_test_one_sample_typed} or
 * {@link wasm_t_test_two_sample_typed}.
 * Must call `.free()` after use.
 */
export declare class WasmTTestResult {
    /** t-statistic. */
    readonly t_stat: number;
    /** Two-tailed p-value. */
    readonly p_value: number;
    /** Degrees of freedom. */
    readonly df: number;
    /** True when p_value < 0.05. */
    readonly significant_at_05: boolean;
    /** True when p_value < 0.01. */
    readonly significant_at_01: boolean;
    free(): void;
}

/**
 * One-sample t-test: tests whether the sample mean equals `mu`.
 *
 * Returns a {@link WasmTTestResult} — **must be freed** after use.
 * All fields are `NaN` / `false` for samples with fewer than 2 elements.
 *
 * @param data — sample values.
 * @param mu   — hypothesised population mean.
 */
export declare function wasm_t_test_one_sample_typed(
    data: Float64Array | number[],
    mu: number
): WasmTTestResult;

/**
 * Two-sample Welch t-test: tests whether the means of `x` and `y` differ.
 *
 * Returns a {@link WasmTTestResult} — **must be freed** after use.
 *
 * @param x — first sample.
 * @param y — second sample.
 */
export declare function wasm_t_test_two_sample_typed(
    x: Float64Array | number[],
    y: Float64Array | number[]
): WasmTTestResult;

// ===========================================================================
// SECTION 4 — Statistics: KS test
// ===========================================================================

/**
 * Result of the Kolmogorov–Smirnov normality test.
 *
 * Obtained from {@link wasm_ks_test_normality}.
 * Must call `.free()` after use.
 */
export declare class WasmKSResult {
    /**
     * KS test statistic D — maximum absolute deviation between the
     * empirical CDF and the Gaussian CDF fit to the data.
     */
    readonly statistic: number;
    /** Approximate two-tailed p-value via the Kolmogorov asymptotic distribution. */
    readonly p_value: number;
    /**
     * True when p_value > 0.05 (i.e. we fail to reject the null hypothesis
     * of normality at α = 0.05).
     */
    readonly is_normal_at_05: boolean;
    free(): void;
}

/**
 * Kolmogorov–Smirnov normality test (Lilliefors variant approximation).
 *
 * Tests whether `data` is consistent with a Normal distribution by comparing
 * the empirical CDF against the Gaussian CDF with the same sample mean and
 * standard deviation.
 *
 * Returns a {@link WasmKSResult} — **must be freed** after use.
 * `statistic` is `NaN` for samples with fewer than 3 elements.
 */
export declare function wasm_ks_test_normality(
    data: Float64Array | number[]
): WasmKSResult;

// ===========================================================================
// SECTION 5 — Statistics: histogram
// ===========================================================================

/**
 * Histogram result.
 *
 * Obtained from {@link wasm_histogram}.
 * Must call `.free()` after use.
 */
export declare class WasmHistogram {
    /** Bin edges — length = n_bins + 1. */
    readonly edges: Float64Array;
    /** Count of observations in each bin — length = n_bins. */
    readonly counts: Uint32Array;
    /**
     * Probability density in each bin: count / (total * bin_width).
     * Integrates to 1 over all bins.
     */
    readonly density: Float64Array;
    /** Number of bins. */
    readonly n_bins: number;
    /** Total number of observations counted. */
    readonly total: number;

    /** Centre of each bin — length = n_bins. */
    bin_centers(): Float64Array;

    /** Width of each bin (uniform spacing). */
    bin_width(): number;

    free(): void;
}

/**
 * Compute a histogram of `data` with `n_bins` equally-spaced bins.
 *
 * The bins span `[min(data), max(data)]`; the last bin is closed on the right.
 * Returns an empty histogram if `data` is empty or `n_bins` is 0.
 *
 * The returned object — **must be freed** after use.
 *
 * @example
 * ```ts
 * const h = wasm_histogram(new Float64Array([1,2,2,3,3,3,4]), 4);
 * console.log(h.edges, h.counts);
 * h.free();
 * ```
 */
export declare function wasm_histogram(
    data: Float64Array | number[],
    n_bins: number
): WasmHistogram;

