/**
 * Power-iteration thin SVD.
 * Returns flat `[U_flat (rows×k), S (k), V_flat (cols×k)]`.
 */
export declare function wasm_svd_power(
    a: Float64Array | number[],
    rows: number,
    cols: number,
    n_components: number
): Float64Array;

/** Frobenius norm of a flat matrix: sqrt(Σ aᵢⱼ²). */
export declare function wasm_frobenius_norm(a: Float64Array | number[]): number;

/** Z-score normalisation: (vᵢ - mean) / std. */
export declare function wasm_normalize(v: Float64Array | number[]): Float64Array;

/** Solve n×n linear system from flat row-major A and vector b. */
export declare function wasm_matrix_solve(
    a: Float64Array | number[],
    b: Float64Array | number[],
    n: number
): Float64Array;

/** Full thin Golub-Reinsch SVD as JSON. */
export declare function wasm_svd(
    data: Float64Array | number[],
    rows: number,
    cols: number
): SvdJsonResult;

/** Structured JSON result from {@link wasm_svd}. */
export interface SvdJsonResult {
    /** Left singular vectors — rows × k (k = min(rows, cols)). */
    readonly U: number[][];
    /** Singular values in descending order — length k. */
    readonly s: number[];
    /** Right singular vectors (transposed) — k × cols. */
    readonly Vt: number[][];
    /** Numerical rank. */
    readonly rank: number;
    readonly rows: number;
    readonly cols: number;
}

