// ===========================================================================
// SECTION 11 — WasmMatrix class
// ===========================================================================

/**
 * Dense row-major f64 matrix with wasm-bindgen bindings.
 *
 * Element `(r, c)` is at index `r * cols + c` in the internal flat storage.
 *
 * Must call `.free()` when done.
 *
 * @example
 * ```ts
 * const m = new WasmMatrix(3, 3);
 * m.set(0, 0, 1); m.set(1, 1, 2); m.set(2, 2, 3);
 * const d = m.determinant();
 * const evs = m.eigenvalues();
 * m.free();
 * ```
 */
export declare class WasmMatrix {
    /**
     * Create a zero-initialised matrix.
     * @throws {Error} if rows or cols is 0.
     */
    constructor(rows: number, cols: number);

    /**
     * Create a matrix from a flat row-major array.
     * @throws {Error} if data.length !== rows * cols.
     */
    static from_vec(rows: number, cols: number, data: number[]): WasmMatrix;

    /** Create an n×n identity matrix. */
    static identity(n: number): WasmMatrix;

    /** Number of rows. */
    rows(): number;

    /** Number of columns. */
    cols(): number;

    /**
     * Get element at (row, col).
     * @throws {Error} if indices are out of bounds.
     */
    get(row: number, col: number): number;

    /**
     * Set element at (row, col).
     * @throws {Error} if indices are out of bounds.
     */
    set(row: number, col: number, val: number): void;

    /** Return a copy of the flat row-major data. */
    to_vec(): number[];

    /** Matrix multiplication: this × other. Throws on shape mismatch. */
    multiply(other: WasmMatrix): WasmMatrix;

    /** Transpose. */
    transpose(): WasmMatrix;

    /** Determinant (square matrices only). */
    determinant(): number;

    /** Matrix inverse (square matrices only). Throws if singular. */
    inverse(): WasmMatrix;

    /** Eigenvalues of a square matrix (real parts via QR iteration). */
    eigenvalues(): number[];

    /** Frobenius norm: sqrt(Σ aᵢⱼ²). */
    norm_frobenius(): number;

    /** Trace (sum of diagonal elements). */
    trace(): number;

    /** Element-wise addition. */
    add(other: WasmMatrix): WasmMatrix;

    /** Element-wise subtraction. */
    sub(other: WasmMatrix): WasmMatrix;

    /** Scalar multiplication. */
    scale(s: number): WasmMatrix;

    free(): void;
}

