    /**
     * Two-sample Welch t-test — returns a typed result **must be freed**.
     */
    tTestTwoSample(x: Float64Array, y: Float64Array): WasmTTestResult;

    /**
     * KS normality test — returns a typed result **must be freed**.
     */
    ksTest(data: Float64Array): WasmKSResult;

    /**
     * Histogram — returns a typed result **must be freed**.
     */
    histogram(data: Float64Array, nBins: number): WasmHistogram;

    /** Spearman rank correlation coefficient. */
